INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10001, "vo_minigame_1004", "ふっふっふ、これでカヤぴぃとボスを見返してやるです！", 1000101, 2, 1, "vo_minigame_1004_top_1_000");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10002, "vo_minigame_1004", "しりとりでの戦い、お兄さんにも手伝ってもらうです", 1000201, 2, 1, "vo_minigame_1004_top_1_003");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10003, "vo_minigame_1004", "どんなケンカも売られた以上は買うのが喧嘩屋だ！やってやるぜ！", 1000301, 1, 2, "vo_minigame_1004_top_1_004");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10004, "vo_minigame_1004", "石板でしりとりか……イノリのヤツおもしろいこと考えるな", 1000401, 1, 2, "vo_minigame_1004_top_1_005");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10005, "vo_minigame_1004", "しりとりだろうがなんだろうが返り討ちにしてやるぜ", 1000501, 1, 2, "vo_minigame_1004_top_1_006");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10006, "vo_minigame_1004", "ぐもも……（オデ、ハラヘッタ）", 1000601, 2, 3, "vo_minigame_1004_top_1_007");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10007, "vo_minigame_1004", "ぐもももも（シリトリ タノシイ）", 1000701, 2, 3, "vo_minigame_1004_top_1_008");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10008, "vo_minigame_1004", "ぐもももも！（イノリ イイヤツ）", 1000801, 2, 3, "vo_minigame_1004_top_1_009");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10009, "vo_minigame_1004", "カヤぴぃ相手でも手加減しないです", 1000901, 2, 1, "vo_minigame_1004_top_2_010");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10009, "vo_minigame_1004", "上等だ！やるからには本気で来いよな", 1000902, 1, 2, "vo_minigame_1004_top_2_011");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10010, "vo_minigame_1004", "カヤぴぃ、謝るなら今のうちです", 1001001, 2, 1, "vo_minigame_1004_top_2_012");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10010, "vo_minigame_1004", "イノリこそ泣きを入れるなら今のうちだぜ？", 1001002, 1, 2, "vo_minigame_1004_top_2_013");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10011, "vo_minigame_1004", "カヤぴぃ、これからは知性の時代ですよ？", 1001101, 2, 1, "vo_minigame_1004_top_2_014");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10011, "vo_minigame_1004", "待て！オレがバカみたいにいうな！！", 1001102, 1, 2, "vo_minigame_1004_top_2_015");
