INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10012, "vo_minigame_1004", "ぐも！（マカセロ！）", 1001202, 2, 3, "vo_minigame_1004_top_2_017");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10013, "vo_minigame_1004", "よしよし、いいですようまくできたらチョコをあげるです！", 1001301, 1, 1, "vo_minigame_1004_top_2_018");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10013, "vo_minigame_1004", "ぐも！（オデ チョコスキ）", 1001302, 2, 3, "vo_minigame_1004_top_2_019");
