INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10015, "vo_minigame_1004", "いくらイノリ相手でも勝ちを譲る気はないからな！", 1001501, 1, 2, "vo_minigame_1004_top_2_025");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10015, "vo_minigame_1004", "望むところです手加減はなしですよ", 1001502, 2, 1, "vo_minigame_1004_top_2_026");
INSERT INTO `v1_bf3c60f7a5328e1d368ff9115091ba586d60f4f5e65612c99caf2a6231040be4` VALUES (10016, "vo_minigame_1004", "へっ、なかなかやるじゃねえか", 1001601, 1, 2, "vo_minigame_1004_top_2_027");
